  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}

#dock button {
  font-family: inherit;
  line-height: 1;
  margin: 0;
  flex-shrink: 0;
  white-space: nowrap;
  appearance: none;
  -webkit-appearance: none;
}

.dock-sep {
  width: 1px;
  height: 18px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.12);
}

#btn-refire {
  width: 78px;
  height: 28px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
#btn-refire:hover {
  background: rgba(255, 255, 255, 0.16);
}

#btn-toggle {
  width: 28px;
  height: 28px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  cursor: pointer;
}
#btn-toggle:hover {
  background: rgba(255, 255, 255, 0.16);
}

#speed-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.speed-pill {
  width: 42px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9999px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.speed-pill:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}
.speed-pill.is-active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.2);
}

#scrubber {
  width: 157px;
  height: 4px;
  margin: 0;
  padding: 0;
  flex-shrink: 0;
  appearance: none;
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.22);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
}
#scrubber::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  background: #ffffff;
  border-radius: 50%;
  border: none;
  cursor: pointer;
}
#scrubber::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}
</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script id="rampart-strategy">
function createStrategy() {
  return { plan() { return []; } };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const record = arguments[3];
  const layout = {
    ground: [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],
    air: [[0,6],[21,6],[21,11],[23,11]],
    slots: [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
  };
  const towers = {
    bolt:   { index:0, cost:50,  damage:26,  period:8,  range:300, splash:0,  slow:0, pierce:false, ground:true,  air:true },
    cannon: { index:1, cost:90,  damage:60,  period:24, range:260, splash:90, slow:0, pierce:false, ground:true,  air:false },
    frost:  { index:2, cost:70,  damage:10,  period:12, range:240, splash:0,  slow:30,pierce:false, ground:true,  air:true },
    lance:  { index:3, cost:120, damage:180, period:36, range:360, splash:0,  slow:0, pierce:true,  ground:true,  air:false },
    flak:   { index:4, cost:80,  damage:40,  period:10, range:320, splash:70, slow:0, pierce:false, ground:false, air:true }
  };
  const kinds = [
    { type:"grunt",    hp:60,  speed:10, bounty:4, leak:1, air:0, first:1, weight:10 },
    { type:"runner",   hp:40,  speed:20, bounty:4, leak:1, air:0, first:2, weight:4 },
    { type:"wisp",     hp:50,  speed:12, bounty:6, leak:2, air:1, first:3, weight:3 },
    { type:"brute",    hp:150, speed:6,  bounty:9, leak:3, air:0, first:4, weight:3 },
    { type:"splitter", hp:90,  speed:8,  bounty:6, leak:2, air:0, first:6, weight:2 },
    { type:"mender",   hp:70,  speed:8,  bounty:7, leak:2, air:0, first:8, weight:1 },
    { type:"splitling",hp:0,   speed:12, bounty:1, leak:1, air:0, first:Infinity, weight:0 }
  ];
  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ''^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t;
      return (t ''^ (t >>> 14)) >>> 0;
    };
  }
  const random = mulberry32(seed);
  const strategy = createStrategy();
  const slots = layout.slots.map(([x,y], slot) => ({ slot, x:100*x+50, y:100*y+50, turret:null }));
  const lengths = [4600, 2600];
  const routes = [layout.ground, layout.air].map((points, air) => {
    const route = [];
    for (let i = 1; i < points.length; i++) {
      const [x,y] = points[i-1];
      const dx = points[i][0]-x, dy = points[i][1]-y;
      const distance = 100*(Math.abs(dx)+Math.abs(dy));
      for (let d = 0; d < distance && route.length <= lengths[air]; d++) {
        route.push([100*x+50+Math.sign(dx)*d, 100*y+50+Math.sign(dy)*d]);
      }
    }
    return route;
  });
  const log = [], queue = new Map(), enemies = [];
  let tick = 0, wave = 0, gold = 250, baseHp = 10, lastId = 0, fallTick = -1;
  let multiplier = 1000, events;
  function generate(w) {
    const eligible = kinds.filter(kind => kind.first <= w);
    const total = eligible.reduce((sum, kind) => sum + kind.weight, 0);
    return Array.from({ length:4+Math.floor(3*w/5) }, () => {
      let r = random() % total;
      for (const kind of eligible) {
        if (r < kind.weight) return kind;
        r -= kind.weight;
      }
    });
  }
  let upcoming = generate(1);
  function spawn(kind, ownWave, maxHp, progress) {
    const { type, air, speed, bounty, leak } = kind;
    const armor = type === "grunt" ? Math.floor(ownWave/4) : type === "brute" ? 6+ownWave : 0;
    const [x,y] = routes[air][progress];
    enemies.push({ id:++lastId, type, air, speed, bounty, leak, armor, wave:ownWave,
      hp:maxHp, maxHp, progress, x, y, slow:0, age:0, remaining:lengths[air]-progress });
  }
  function view(e) {
    return { id:e.id, type:e.type, hp:e.hp, maxHp:e.maxHp, x:e.x, y:e.y, air:e.air,
      armor:e.armor, speed:e.speed, slowed:e.slow > 0, remaining:e.remaining };
  }
  function emit(code, a, b) {
    log.push([tick,code,a,b]);
  }
  function visual(code, fields) {
    if (record) events.push({ code, ...fields });
  }
  function inRange(a, b, rr) {
    const dx = a.x-b.x, dy = a.y-b.y;
    return dx*dx+dy*dy <= rr;
  }
  function snapshot() {
    record(tick, {
      wave, gold, baseHp, events,
      nextWave:upcoming.map(kind => kind.type),
      turrets:slots.map(s => s.turret && { type:s.turret.type, tier:s.turret.tier,
        aimX:s.turret.aimX, aimY:s.turret.aimY }),
      enemies:enemies.map(e => ({ id:e.id, type:e.type, x:e.x, y:e.y, hp:e.hp, maxHp:e.maxHp,
        progress:e.progress, slowed:e.slow > 0 }))
    }, layout);
  }
  for (; tick < maxTicks; tick++) {
    if (record) events = [];
    if (tick >= 20 && (tick-20)%40 === 0) {
      wave++;
      gold += Math.min(50, Math.floor(gold*5/100)) + 10 + 2*wave;
      const spawning = upcoming;
      upcoming = generate(wave+1);
      if (wave > 1) multiplier = Math.floor(multiplier*108/100);
      visual("W", { wave, x:1200 });
      const actions = strategy.plan({
        tick, wave, gold, baseHp, enemies:enemies.map(view), nextWave:upcoming.map(kind => kind.type),
        slots:slots.map(s => ({ slot:s.slot, x:s.x, y:s.y, turret:s.turret &&
          { type:s.turret.type, tier:s.turret.tier, spent:s.turret.spent } }))
      });
      if (Array.isArray(actions)) for (const action of actions.slice(0,32)) {
        if (!action || !Number.isInteger(action.slot)) continue;
        const s = slots[action.slot];
        if (!s) continue;
        const { slot, x, y, turret } = s;
        if (action.op === "build" && !turret && typeof action.type === "string" &&
            Object.prototype.hasOwnProperty.call(towers, action.type)) {
          const def = towers[action.type];
          if (gold < def.cost) continue;
          gold -= def.cost;
          s.turret = { ...def, type:action.type, tier:1, spent:def.cost, cooldown:0, aimX:x+100, aimY:y };
          emit("B", slot, def.index);
          visual("B", { x, y, type:action.type });
        } else if (action.op === "upgrade" && turret && turret.tier < 3) {
          const cost = turret.cost*turret.tier;
          if (gold < cost) continue;
          gold -= cost;
          turret.spent += cost;
          turret.damage = Math.floor(turret.damage*16/10);
          turret.range += 30;
          emit("U", slot, ++turret.tier);
          visual("U", { x, y, type:turret.type });
        } else if (action.op === "sell" && turret) {
          gold += Math.floor(turret.spent*70/100);
          s.turret = null;
          emit("S", slot, 0);
          visual("S", { x, y, type:turret.type });
        }
      }
      spawning.forEach((kind, index) => {
        const due = tick+4*index;
        if (!queue.has(due)) queue.set(due, []);
        queue.get(due).push([kind,wave,Math.floor(kind.hp*multiplier/1000)]);
      });
    }
    const due = queue.get(tick);
    if (due) {
      for (const [kind, ownWave, hp] of due) spawn(kind, ownWave, hp, 0);
      queue.delete(tick);
    }
    for (let i = 0; i < enemies.length; i++) {
      const e = enemies[i];
      e.progress += e.slow ? Math.floor(e.speed*60/100) : e.speed;
      e.remaining = lengths[e.air]-e.progress;
      if (e.remaining > 0) {
        [e.x,e.y] = routes[e.air][e.progress];
        continue;
      }
      baseHp -= e.leak;
      enemies.splice(i--,1);
      emit("L", e.id, baseHp);
      visual("L", { x:2350, y:1150, baseHp, amount:e.leak });
      if (baseHp <= 0) {
        fallTick = tick;
        emit("F", wave, 0);
        visual("F", { x:2350, y:1150 });
        break;
      }
    }
    if (fallTick >= 0) {
      if (record) snapshot();
      break;
    }
    for (const e of enemies) {
      e.age++;
      if (e.type === "mender" && e.age%20 === 0) {
        for (const other of enemies) if (inRange(e, other, 22500)) {
          other.hp = Math.min(other.maxHp, other.hp + Math.floor(other.maxHp*8/100));
        }
        visual("H", { x:e.x, y:e.y, radius:150 });
      }
    }
    for (const s of slots) {
      const t = s.turret;
      if (!t || (t.cooldown > 0 && --t.cooldown > 0)) continue;
      const candidates = [];
      for (const e of enemies) {
        if ((e.air ? t.air : t.ground) && inRange(s, e, t.range*t.range)) candidates.push(e);
      }
      if (!candidates.length) continue;
      let target;
      if (typeof strategy.target === "function") {
        const id = strategy.target({ slot:s.slot, type:t.type, tier:t.tier, x:s.x, y:s.y, range:t.range }, candidates.map(view));
        target = candidates.find(e => e.id === id);
      }
      if (!target) {
        target = candidates[0];
        for (const e of candidates) if (e.remaining < target.remaining) target = e;
      }
      t.aimX = target.x;
      t.aimY = target.y;
      t.cooldown = t.period;
      visual("T", { type:t.type, slot:s.slot, tier:t.tier, x:s.x, y:s.y,
        tx:target.x, ty:target.y, air:target.air, radius:t.splash });
      if (t.splash) {
        for (const e of enemies) if ((e.air ? t.air : t.ground) && inRange(target,e,t.splash*t.splash)) {
          e.hp -= Math.max(1, t.damage-(t.pierce ? 0 : e.armor));
          if (t.slow) e.slow = t.slow;
        }
      } else {
        target.hp -= Math.max(1, t.damage-(t.pierce ? 0 : target.armor));
        if (t.slow) target.slow = t.slow;
      }
      for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (e.hp > 0) continue;
        enemies.splice(i--,1);
        gold += e.bounty;
        emit("K", e.id, s.slot);
        visual("K", { id:e.id, type:e.type, x:e.x, y:e.y, air:e.air });
        if (e.type === "splitter") {
          const hp = Math.max(1, Math.floor(e.maxHp/4));
          for (let j = 0; j < 3; j++) spawn(kinds[6], e.wave, hp, e.progress);
        }
      }
    }
    for (const e of enemies) if (e.slow > 0) e.slow--;
    if (record) snapshot();
  }
  const serialized = JSON.stringify(log);
  let hash = 0x811c9dc5;
  for (let i = 0; i < serialized.length; i++) hash = Math.imul(hash ''^ serialized.charCodeAt(i), 0x01000193);
  return { score:Number((((fallTick < 0 ? maxTicks : fallTick)-20)/40).toFixed(2)),
    fallTick, log, hash:(hash>>>0).toString(16).padStart(8,"0") };
}
</script>
EOF
